# A corregir: un solo attempt
def retry_call(fn, max_attempts=3):
    return fn()

n = {"c": 0}

def flaky():
    n["c"] += 1
    if n["c"] < 3:
        raise TimeoutError("x")
    return "done"

try:
    print(retry_call(flaky))
except TimeoutError as e:
    print("failed", e)
